import sys
import json

def factorize(n):
    factors = []
    d = 2
    while d * d <= n:
        while (n % d) == 0:
            if d not in factors:
                factors.append(d)
            n //= d
        d += 1
    if n > 1:
        if n not in factors:
            factors.append(n)
    return sorted(factors)

def main():
